public class UrlBuilderTest {

    @Test
    public void constructorNoUrl() {
        UrlBuilder builder = new UrlBuilder(null);
        assertNotNull(builder);
    }

    @Test
    public void appendKeyVal_NoKeyOrValue() {
        Connection.KeyVal kv = new Connection.KeyVal();
        try {
            UrlBuilder builder = new UrlBuilder(new URL("http://example.com"));
            builder.appendKeyVal(kv);
            fail("Expected UnsupportedEncodingException");
        } catch (UnsupportedEncodingException e) {
            // expected
        }
    }

    @Test
    public void appendKeyVal_OnlyKey() throws UnsupportedEncodingException {
        Connection.KeyVal kv = new Connection.KeyVal();
        kv.setValue(StringUtil.UTF_8);
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com"));
        builder.appendKeyVal(kv);
        assertThrows(UnsupportedEncodingException.class, () -> builder.build());
    }

    @Test
    public void appendKeyVal_OnlyValue() throws UnsupportedEncodingException {
        Connection.KeyVal kv = new Connection.KeyVal();
        kv.setKey(StringUtil.UTF_8);
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com"));
        builder.appendKeyVal(kv);
        assertThrows(UnsupportedEncodingException.class, () -> builder.build());
    }

    @Test
    public void appendKeyVal_KeyAndValue() throws UnsupportedEncodingException {
        Connection.KeyVal kv = new Connection.KeyVal();
        kv.setKey(StringUtil.UTF_8);
        kv.setValue(StringUtil.UTF_8);
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com"));
        builder.appendKeyVal(kv);
        String expectedUrl = "http://example.com?utf8=utf8";
        assertEquals(expectedUrl, builder.build().toString());
    }

    @Test
    public void appendQuery_ExistingQuery() {
        Connection.KeyVal kv = new Connection.KeyVal();
        kv.setKey(StringUtil.UTF_8);
        kv.setValue(StringUtil.UTF_8);
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com?existing=param"));
        builder.appendKeyVal(kv);
        String expectedUrl = "http://example.com?utf8=utf8&existing=param";
        assertEquals(expectedUrl, builder.build().toString());
    }

    @Test
    public void appendQuery_NewQuery() {
        Connection.KeyVal kv = new Connection.KeyVal();
        kv.setKey(StringUtil.UTF_8);
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com"));
        builder.appendKeyVal(kv);
        String expectedUrl = "http://example.com?utf8=utf8";
        assertEquals(expectedUrl, builder.build().toString());
    }

    @Test
    public void buildInvalidUrl() {
        assertThrows(MalformedURLException.class, () -> new UrlBuilder(new URL("invalid://example.com")));
    }
